# Surah Yusuf (chapter 12) — part 3: ayat 21-30 (IDs 1617-1626)
SURAH = 12

ENTRIES = {
1617: (
"اور — مصر — میں — اسے — خریدنے والے — نے — اپنی — بیوی — سے — کہا — اسے — عزت سے — رکھ — شاید — یہ — ہمارے لیے فائدہ — دے — یا — ہم — اسے — بیٹا — بنا لیں — اور — اسی — طرح — ہم نے — یوسفؑ — کو — زمین — میں — جگہ — دی — اور — تاکہ — ہم — اسے — باتوں کی — تاویل — سکھائیں — اور — اللہ — اپنے — معاملے — پر — غالب — ہے — لیکن — اکثر لوگ — نہیں جانتے",
"""۱۔ مصر کے عزیز — نے — یوسفؑ — کو گھر میں عزت دی — اور — اللہ نے انہیں — جگہ دی۔
۲۔ ’’وَقَالَ الَّذِي اشْتَرَاهُ مِن مِّصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَن يَنفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِن تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — اور — مصر — میں — اسے — خریدنے والے — نے — اپنی — بیوی — سے — کہا — اسے — عزت سے — رکھ — شاید — یہ — ہمارے لیے فائدہ — دے — یا — ہم — اسے — بیٹا — بنا لیں — اور — اسی — طرح — ہم نے — یوسفؑ — کو — زمین — میں — جگہ — دی — اور — تاکہ — ہم — اسے — باتوں کی — تاویل — سکھائیں — اور — اللہ — اپنے — معاملے — پر — غالب — ہے — لیکن — اکثر لوگ — نہیں جانتے — یعنی مصر کے عزیز — نے اپنی بیوی سے کہا — اسے — عزت سے — رکھیں — شاید یہ ہمارے لیے — فائدہ — دے — یا — ہم — اس — کو بیٹا — بنا لیں — اور — اسی طرح ہم نے — یوسفؑ کو — زمین — میں — جگہ — دی — اور تاکہ ہم اسے — باتوں کی تاویل — سکھائیں — اور — اللہ — اپنے معاملے — پر غالب — ہے — لیکن اکثر — لوگ — نہیں جانتے۔
۳۔ عملی سبق: اللہ — اپنے — معاملے — پر — غالب — ہے؛ وہ — جو — چاہے — کرتا ہے۔"""
),
1618: (
"اور — جب — وہ — اپنی جوانی — کو — پہنچ — گئے — تو — ہم نے — انہیں — حکم اور علم — دیا — اور — اسی طرح — ہم — نیک لوگوں — کو — بدلہ — دیتے ہیں",
"""۱۔ یوسفؑ کو — جوانی پر — حکم اور علم — عطا — کیا گیا۔
۲۔ ’’وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ‘‘ — اور — جب — وہ — اپنی جوانی — کو — پہنچ — گئے — تو — ہم نے — انہیں — حکم اور علم — دیا — اور — اسی طرح — ہم — نیک لوگوں — کو — بدلہ — دیتے ہیں — یعنی جب — یوسفؑ — اپنی جوانی — کو پہنچے — ہم نے انہیں — حکم اور علم — عطا — کیا — اور — اسی طرح ہم — نیکوکاروں — کو — بدلہ — دیتے ہیں۔
۳۔ عملی سبق: نیکی — کا — بدلہ — علم اور حکمت — ہے۔"""
),
1619: (
"اور — وہ — عورت — جس — کے گھر — وہ تھے — اس نے — ان — سے — اپنی — بات کی — اور — دروازے — بند کر لیے — اور — کہا — آ جاؤ — انہوں نے کہا — اللہ — کی پناہ — بے شک — وہ — میرا — رب — ہیں — جن — نے — میری قیامگاہ — بہتر — بنائی — بے شک — ظالم — کامیاب — نہیں ہوتے",
"""۱۔ یوسفؑ — امتحان — میں — اللہ — کی پناہ — چاہتے ہیں۔
۲۔ ’’وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَن نَّفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ‘‘ — اور — وہ — عورت — جس — کے گھر — وہ تھے — اس نے — ان — سے — اپنی — بات کی — اور — دروازے — بند کر لیے — اور — کہا — آ جاؤ — انہوں نے کہا — اللہ — کی پناہ — بے شک — وہ — میرا — رب — ہیں — جن — نے — میری قیامگاہ — بہتر — بنائی — بے شک — ظالم — کامیاب — نہیں ہوتے — یعنی جس عورت کے پاس — یوسفؑ تھے — اس — نے ان سے اپنی خواہش ظاہر — کی — اور دروازے بند کر لیے — کہا — آ جاؤ — یوسفؑ نے — کہا — اللہ کی پناہ — بے شک وہ میرا رب — ہیں — جنہوں نے میری قیامگاہ — بہتر — بنائی — بے شک ظالم کامیاب — نہیں ہوتے۔
۳۔ عملی سبق: امتحان — میں — اللہ — کی پناہ — سب سے مضبوط — قلعہ ہے۔"""
),
1620: (
"اور — اس نے — ان — کا ارادہ کیا — اور — انہوں — نے بھی — اس — کا ارادہ کر لیا — ہوتے — مگر — وہ نہیں دیکھا — اپنے رب — کی دلیل — اسی طرح — כדי — ہم — اس — سے — برائی اور بے حیائی — ہٹا — دیں؛ بے شک — وہ — ہمارے — چُنے ہوئے — بندوں — میں سے — ہیں",
"""۱۔ یوسفؑ — کو — اللہ — کی دلیل — نظر آئی؛ برائی — سے — محفوظ رہے۔
۲۔ ’’وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَن رَّأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ‘‘ — اور — اس نے — ان — کا ارادہ کیا — اور — انہوں — نے بھی — اس — کا ارادہ کر لیا — ہوتے — مگر — وہ نہیں دیکھا — اپنے رب — کی دلیل — اسی طرح — כדי — ہم — اس — سے — برائی اور بے حیائی — ہٹا — دیں؛ بے شک — وہ — ہمارے — چُنے ہوئے — بندوں — میں سے — ہیں — یعنی عورت — نے ان کا ارادہ کیا — اور — وہ — بھی — انسان کی حدود میں رہے — مگر — انہوں نے — اپنے رب کی — دلیل/نشانی — دیکھ لی؛ اسی طرح — ہم نے — ان — سے برائی اور بے حیائی — ہٹادی — بے شک وہ — ہمارے مخلص بندوں — میں سے — ہیں — انبیائے کرام (ع) — گناہوں سے — معصوم ہوتے ہیں — یہ — واقعہ — انسانی ارادے کی آزمائش — اور — عصمتِ انبیاءؑ — کا — عظیم — ثبوت — ہے۔
۳۔ عملی سبق: اپنے رب کی دلیل — سامنے — رہے — تو — کوئی — برائی — کامیاب — نہیں۔"""
),
1621: (
"اور — وہ — دونوں — دروازے کی طرف — دوڑے — اور — اس — نے — ان — کے کرتے — کو — پیچھے سے — پھاڑ دیا — اور — انہوں — نے — دروازے — کے پاس — اس — کے خاوند — کو — پایا — اس — نے کہا — اس شخص — کی جزا — کیا ہے — جس — نے — تیرے اہل — سے برائی — کا ارادہ کیا — سوائے — اس — کے کہ — اس — کو — قید — کیا جائے — یا — دردناک عذاب — دیا جائے",
"""۱۔ دروازے کی طرف — دوڑنا — کرتا پھٹنا — خاوند — کو — scene — نظر آیا۔
۲۔ ’’وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ‘‘ — اور — وہ — دونوں — دروازے کی طرف — دوڑے — اور — اس — نے — ان — کے کرتے — کو — پیچھے سے — پھاڑ دیا — اور — انہوں — نے — دروازے — کے پاس — اس — کے خاوند — کو — پایا — اس — نے کہا — اس شخص — کی جزا — کیا ہے — جس — نے — تیرے اہل — سے برائی — کا ارادہ کیا — سوائے — اس — کے کہ — اس — کو — قید — کیا جائے — یا — دردناک عذاب — دیا جائے — یعنی وہ — دونوں — دروازے کی طرف — دوڑے — اور مرد کے کرتے کو — پیچھے سے — پھاڑ دیا — اور — دروازے — کے پاس — اس — کے خاوند — سے — ملاقات ہوئی — اس — نے کہا — کوئی شخص جو — تیرے گھر والوں سے برائی کا — ارادہ کرے — اس کی جزا — کیا ہے — سوائے اس — کے کہ اسے — قید — کیا جائے — یا — دردناک عذاب — دیا — جائے۔
۳۔ عملی سبق: سچائی — کی نشانیاں — اکثر — ظاہری — ہوتی ہیں؛ انصاف — کریں۔"""
),
1622: (
"انہوں نے کہا — اسی — نے — مجھ — سے — اپنی — بات — کی — اور — اس — کے — اہل — کے ایک گواہ — نے — گواہی — دی — اگر — اس کا کرتا — آگے سے — پھٹا ہو — تو — وہ — سچی ہے — اور — وہ — جھوٹ بولنے والوں — میں سے — ہے",
"""۱۔ یوسفؑ — کا دفاع؛ اس کے گھر والوں کے گواہ — کی فیصلہ کن گواہی۔
۲۔ ’’قَالَ هِيَ رَاوَدَتْنِي عَن نَّفْسِي وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَا إِن كَانَ قَمِيصُهُ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ‘‘ — انہوں نے کہا — اسی — نے — مجھ — سے — اپنی — بات — کی — اور — اس — کے — اہل — کے ایک گواہ — نے — گواہی — دی — اگر — اس کا کرتا — آگے سے — پھٹا ہو — تو — وہ — سچی ہے — اور — وہ — جھوٹ بولنے والوں — میں سے — ہے — یعنی یوسفؑ نے کہا — اسی — عورت نے — مجھ سے — اپنی — بات — کی — اور — اس — کے اہل — کے ایک گواہ — نے — گواہی دی — اگر اسے — آگے سے — یہ کرتا پھٹا ہو — تو وہ — سچی ہے — اور — وہ — جھوٹ بولنے والوں — میں — سے — ہے۔
۳۔ عملی سبق: گواہی — انصاف — کا — بنیاد — ہے۔"""
),
1623: (
"اور — اگر — اس کا کرتا — پیچھے — سے — پھٹا — ہو — تو — وہ — جھوٹی — ہے — اور — وہ — سچ بولنے والوں — میں سے — ہے",
"""۱۔ کرتے کا پھٹنا — پیچھے سے — جھوٹ — کا — ثبوت۔
۲۔ ’’وَإِن كَانَ قَمِيصُهُ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ‘‘ — اور — اگر — اس کا کرتا — پیچھے — سے — پھٹا — ہو — تو — وہ — جھوٹی — ہے — اور — وہ — سچ بولنے والوں — میں سے — ہے — یعنی اور اگر — اس — کا کرتا — پیچھے سے — پھٹا ہو — تو وہ — جھوٹی — ہے — اور — وہ — سچ بولنے والوں — میں — سے — ہے۔
۳۔ عملی سبق: ثبوت — کی روشنی — میں — فیصلہ — کرو؛ قیاس نہیں۔"""
),
1624: (
"پس — جب — اس — نے — دیکھا — اس کے کرتے — کو — پیچھے سے — پھٹا — ہوا — تو — کہا — یہ — تم — عورتوں — کی — چال ہے — بے شک — تمہاری چال — بڑی — ہے",
"""۱۔ عورت کا — کرتے پیچھے — سے پھٹا — خاوند — کا — قبول کرنا؛ یہ — عورتوں کی چال ہے۔
۲۔ ’’فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ‘‘ — پس — جب — اس — نے — دیکھا — اس کے کرتے — کو — پیچھے سے — پھٹا — ہوا — تو — کہا — یہ — تم — عورتوں — کی — چال ہے — بے شک — تمہاری چال — بڑی — ہے — یعنی جب — خاوند نے — دیکھا — اس کا — کرتا — پیچھے — سے — پھٹا ہوا ہے — تو اس نے کہا — یہ — تم — عورتوں — کی — چال ہے؛ بے شک — تمہاری — چال — بڑی — ہے۔
۳۔ عملی سبق: ثبوت — ملے — تو — مسئلہ — حل ہو جاتا ہے؛ انصاف — کرو۔"""
),
1625: (
"اے — یوسفؑ — اس — سے — پرہیز کرو — اور — تو — اپنے گناہ — کے لیے — بخشش — مانگو — بے شک — تو — خطا — کرنے والوں — میں — ہے",
"""۱۔ خاوند — یوسفؑ کو — پرہیز — اور — بیوی کو — استغفار — کا حکم دیتا ہے۔
۲۔ ’’يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنبِكِ إِنَّكِ كُنتِ مِنَ الْخَاطِئِينَ‘‘ — اے — یوسفؑ — اس — سے — پرہیز کرو — اور — تو — اپنے گناہ — کے لیے — بخشش — مانگو — بے شک — تو — خطا — کرنے والوں — میں — ہے — یعنی اے یوسفؑ — اس سے پرہیز کرو؛ اور — تو — اے بیوی — اپنے گناہ کے لیے استغفار — کرو — بے شک — تو — خطا — کرنے والوں — میں — سے ہے۔
۳۔ عملی سبق: گناہ — کا — اعتراف — اور — استغفار — توبہ — کے — دو ستون — ہیں۔"""
),
1626: (
"اور — شہر — میں — کچھ عورتوں — نے — کہا — عزیز کی بیوی — اپنے — غلام — سے — اپنی — بات کرتی ہے — اس — کا — عشق — اس — کے دل — تک — پہنچ — گیا — بے شک — ہم — اسے — کھلی گمراہی — میں دیکھتی ہیں",
"""۱۔ شہر میں خبر — عزیز کی بیوی — کی — محبت — مشہور ہو جاتی ہے۔
۲۔ ’’وَقَالَ نِسْوَۃٌ فِي الْمَدِينَۃِ امْرَأَتُ الْعَزِيزِ تُرَاوِدُ فَتَاهَا عَن نَّفْسِهِ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَاهَا فِي ضَلَالٍ مُّبِينٍ‘‘ — اور — شہر — میں — کچھ عورتوں — نے — کہا — عزیز کی بیوی — اپنے — غلام — سے — اپنی — بات کرتی ہے — اس — کا — عشق — اس — کے دل — تک — پہنچ — گیا — بے شک — ہم — اسے — کھلی گمراہی — میں دیکھتی ہیں — یعنی شہر کی کچھ عورتوں — نے کہا — عزیز کی بیوی — اپنے غلام کی طرف — مائل — ہے؛ اس — کا عشق — اس کے دل — تک پہنچ گیا — بے شک — ہم — اسے — کھلی گمراہی — میں — دیکھتی — ہیں۔
۳۔ عملی سبق: خلوت — کے گناہ — اکثر — ظاہر — ہو جاتے ہیں؛ اللہ سے — ڈرو۔"""
),
}
